mapper.select:
SELECT a.id, a.camera_id, a.up_region_id, b.camera_name as cameraName, c.region_name as upRegionName, ROUND(TIMESTAMPDIFF(SECOND,a.start_time,a.end_time) / 60,1) AS recordTimeValue, a.start_time, a.end_time, a.file_path, a.file_name FROM t_record_file a LEFT JOIN t_camera_info b ON a.camera_id = b.camera_id LEFT JOIN t_std_region c ON a.up_region_id = c.region_id WHERE 1=1 and a.end_time is not null
AND a.camera_id = #{cameraId,jdbcType=VARCHAR}
and a.start_time >= #{startTime, jdbcType=TIMESTAMP} AND a.start_time <= #{endTime, jdbcType=TIMESTAMP}
ORDER BY a.start_time DESC
